# A fixed-capacity least-recently-used cache.
#
# Ruby hashes preserve insertion order, so the first key is always the least
# recently used. Reads and writes move their key to the end.
class LRUCache
  attr_reader :capacity

  def initialize(capacity)
    unless capacity.is_a?(Integer) && capacity >= 0
      raise ArgumentError, "capacity must be a non-negative Integer"
    end

    @capacity = capacity
    @cache = {}
  end

  def get(key)
    return nil unless @cache.key?(key)

    value = @cache.delete(key)
    @cache[key] = value
    value
  end
  alias [] get

  def put(key, value)
    @cache.delete(key)
    @cache[key] = value
    @cache.shift while @cache.size > @capacity
    value
  end
  alias []= put

  def delete(key)
    @cache.delete(key)
  end

  def key?(key)
    @cache.key?(key)
  end
  alias include? key?

  def size
    @cache.size
  end

  def empty?
    @cache.empty?
  end

  def clear
    @cache.clear
    self
  end
end
